(() => {
  'use strict';
  const config = (document.body.classList.contains('night-body') ? window.BAHRAM_NIGHT_MUSIC : window.BAHRAM_MUSIC) || {};
  const reduced = matchMedia('(prefers-reduced-motion: reduce)');
  const isNight = document.body.classList.contains('night-body');
  const musicScope = config.storageKey || (isNight ? 'night' : 'main');
  const safeGet = key => { try { return sessionStorage.getItem(key); } catch { return null; } };
  const safeSet = (key, value) => { try { sessionStorage.setItem(key, String(value)); } catch {} };
  document.body.insertAdjacentHTML('beforeend', `<div class="reading-progress" aria-hidden="true"></div><div class="scene-curtain" aria-hidden="true"><span>ISSUE 26</span></div><div class="sound-dock" role="group" aria-label="Музыкальное сопровождение"><button class="music-play" id="music-play" aria-label="Включить музыку" aria-pressed="false">▶</button><div class="music-meta"><strong id="music-title"></strong><small id="music-status">МУЗЫКА ВЫКЛЮЧЕНА</small></div><div class="music-wave" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div><input class="music-volume" type="range" min="0" max="100" value="35" aria-label="Громкость музыки"><label class="music-upload" title="Выбрать свою песню с устройства">＋<input id="music-file" type="file" accept="audio/*" aria-label="Выбрать свою песню с устройства"></label></div><div class="chapter-label" aria-hidden="true">ISSUE 26</div>`);
  let ctx, master, mediaSource, mediaGain, timer, playing = false, beat = 0, audio, blobURL, ducked = false, scrollFrame = 0;
  let volume = Number(safeGet('bahram-volume') || .35);
  let track = { src: config.src || '', title: config.title || 'Тема выпуска · Original score', artist: config.artist || 'BAHRAM / ISSUE 26' };
  const playButton = document.getElementById('music-play'), title = document.getElementById('music-title'), status = document.getElementById('music-status');
  const volumeInput = document.querySelector('.music-volume'), dock = document.querySelector('.sound-dock');
  const timeKey = () => 'bahram-track-time-' + musicScope + '-' + (track.src.startsWith('blob:') ? 'custom' : track.src);
  title.textContent = track.title; volumeInput.value = Math.round(volume * 100);
  function error(message) { document.querySelector('.music-error')?.remove(); const el = document.createElement('div'); el.className = 'music-error'; el.setAttribute('role','status'); el.textContent = message; document.body.append(el); setTimeout(()=>el.remove(),5500); }
  function level() {
    const target = volume * (ducked ? .38 : 1), smoothing = ducked ? .12 : .45;
    dock.dataset.ducked = String(ducked);
    if(master&&ctx) master.gain.setTargetAtTime(playing ? target * .28 : 0,ctx.currentTime,smoothing);
    if(mediaGain&&ctx) { mediaGain.gain.cancelScheduledValues(ctx.currentTime); mediaGain.gain.setTargetAtTime(playing ? target : 0,ctx.currentTime,smoothing); audio.volume=1; }
    else if(audio) audio.volume = Math.min(1,target);
  }
  async function prepareMediaMix() {
    try { const AudioContextClass=window.AudioContext||window.webkitAudioContext;
      if(!AudioContextClass)return;
      if(!ctx)ctx=new AudioContextClass();
      if(!mediaSource){mediaSource=ctx.createMediaElementSource(audio);mediaGain=ctx.createGain();mediaGain.gain.value=0;mediaSource.connect(mediaGain);mediaGain.connect(ctx.destination);}
      await ctx.resume();
    } catch { /* HTML audio remains usable when Web Audio is unavailable. */ }
  }
  function sync() { dock.classList.toggle('playing',playing); playButton.textContent = playing?'Ⅱ':'▶'; playButton.setAttribute('aria-label',playing?'Выключить музыку':'Включить музыку'); playButton.setAttribute('aria-pressed',String(playing)); status.textContent = playing?(track.src?'СЕЙЧАС ИГРАЕТ · '+track.artist:'ОРИГИНАЛЬНАЯ ТЕМА ВЫПУСКА'):'МУЗЫКА ВЫКЛЮЧЕНА'; safeSet('bahram-playing',playing); document.dispatchEvent(new CustomEvent('bahram:musicstate',{detail:{playing}})); }
  const harmony = [[146.83,174.61,220,261.63],[130.81,164.81,196,246.94],[116.54,146.83,174.61,220],[130.81,164.81,196,233.08]];
  function tone(hz,duration,gain,type='sine',delay=0) { const now=ctx.currentTime+delay,o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.value=hz;g.gain.setValueAtTime(.00001,now);g.gain.exponentialRampToValueAtTime(gain,now+.025);g.gain.exponentialRampToValueAtTime(.00001,now+duration);o.connect(g);g.connect(master);o.start(now);o.stop(now+duration+.1);o.onended=()=>{o.disconnect();g.disconnect();}; }
  function tick() { if(!playing||track.src||document.hidden)return;const chord=harmony[Math.floor(beat/16)%4];if(beat%16===0){chord.forEach((f,i)=>tone(f,4.4,.15,'sine',i*.035));tone(chord[0]/2,1.8,.42);}if(beat%4===0)tone(chord[(beat/4)%4]*2,.8,.13,'triangle');if(beat%8===4)tone(chord[0]/2,.6,.21);if(beat%2===0)tone(4400,.025,.012,'triangle');beat++; }
  async function play() { safeSet('bahram-resume',false);try { if(track.src){if(!audio){audio=new Audio(track.src);audio.loop=true;audio.preload='metadata';audio.id='birthday-audio';audio.hidden=true;document.body.append(audio);audio.addEventListener('error',()=>{pause();error('Не удалось открыть песню. Выбери другой аудиофайл кнопкой ＋.');});const saved=Number(safeGet(timeKey())||0);audio.addEventListener('loadedmetadata',()=>{if(saved<audio.duration)audio.currentTime=saved;},{once:true});}await prepareMediaMix();playing=true;level();await audio.play();}else{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)throw Error('no audio');if(!ctx){ctx=new Audio();master=ctx.createGain();master.gain.value=0;master.connect(ctx.destination);}await ctx.resume();playing=true;level();tick();clearInterval(timer);timer=setInterval(tick,170.45);}sync();}catch{playing=false;sync();error('Браузер пока не разрешил звук. Нажми ▶ ещё раз.');} }
  function pause(){safeSet('bahram-resume',false);playing=false;clearInterval(timer);if(audio){safeSet(timeKey(),audio.currentTime);audio.pause();}level();sync();}
  playButton.addEventListener('click',()=>playing?pause():play());
  volumeInput.addEventListener('input',()=>{volume=Number(volumeInput.value)/100;safeSet('bahram-volume',volume);level();});
  document.addEventListener('bahram:duck',e=>{ducked=Boolean(e.detail);level();});
  function database(){return new Promise((resolve,reject)=>{if(!window.indexedDB){reject(Error('no storage'));return;}const request=indexedDB.open('bahram-local-music',1);request.onupgradeneeded=()=>request.result.createObjectStore('tracks');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
  async function restoreLocalTrack(){try{const db=await database();const file=await new Promise((resolve,reject)=>{const r=db.transaction('tracks').objectStore('tracks').get('selected-'+musicScope);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});db.close();if(file){blobURL=URL.createObjectURL(file);track={src:blobURL,title:file.name.replace(/\.[^.]+$/,''),artist:'ПЕСНЯ С ЭТОГО УСТРОЙСТВА'};title.textContent=track.title;}}catch{}}
  document.getElementById('music-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(file.size>60*1024*1024){error('Выбери аудиофайл меньше 60 МБ.');return;}if(file.type&&!file.type.startsWith('audio/')){error('Нужен аудиофайл: MP3, M4A, WAV или OGG.');return;}pause();if(blobURL)URL.revokeObjectURL(blobURL);audio?.remove();mediaSource?.disconnect();mediaGain?.disconnect();mediaSource=null;mediaGain=null;audio=null;blobURL=URL.createObjectURL(file);track={src:blobURL,title:file.name.replace(/\.[^.]+$/,''),artist:'ПЕСНЯ С ЭТОГО УСТРОЙСТВА'};title.textContent=track.title;safeSet(timeKey(),0);try{const db=await database();await new Promise((resolve,reject)=>{const t=db.transaction('tracks','readwrite');t.objectStore('tracks').put(file,'selected-'+musicScope);t.oncomplete=resolve;t.onerror=()=>reject(t.error);});db.close();}catch{error('Песня играет в этой вкладке. Сохранение между страницами недоступно.');}await play();});
  let navigating=false;
  const curtain=document.querySelector('.scene-curtain');
  document.addEventListener('click',e=>{const link=e.target.closest('a[href]');if(!link||link.target==='_blank'||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||e.button!==0)return;const url=new URL(link.href,location.href);if(url.origin!==location.origin||!url.pathname.endsWith('.html')&&url.pathname!==location.pathname)return;if(navigating)return;const local=url.pathname===location.pathname&&url.hash;if(reduced.matches)return;e.preventDefault();navigating=true;curtain.querySelector('span').textContent=local?(url.hash==='#letter'?'ЛИЧНО ТЕБЕ.':url.hash==='#top'?'BAHRAM.':'СЛЕДУЮЩАЯ ГЛАВА'):(url.pathname.endsWith('night-shift.html')?'NIGHT SHIFT':'BAHRAM.');curtain.classList.remove('uncover');curtain.classList.add('cover');setTimeout(()=>{if(audio)safeSet(timeKey(),audio.currentTime);if(local){const target=document.getElementById(decodeURIComponent(url.hash.slice(1)));if(target){target.querySelectorAll('.reveal').forEach(x=>x.classList.add('visible'));target.scrollIntoView({behavior:'instant',block:'start'});history.pushState(null,'',url.hash);}curtain.classList.remove('cover');curtain.classList.add('uncover');setTimeout(()=>{curtain.classList.remove('uncover');navigating=false;},500);}else location.href=url.href;},430);});
  function updateScroll(){scrollFrame=0;const height=document.documentElement.scrollHeight-innerHeight;document.querySelector('.reading-progress').style.width=`${height>0?scrollY/height*100:0}%`;if(!isNight&&!reduced.matches){const hero=document.querySelector('.hero');if(hero&&scrollY<hero.offsetHeight){hero.style.setProperty('--hero-scale',String(1+Math.min(scrollY/hero.offsetHeight,.9)*.12));hero.style.setProperty('--hero-copy-opacity',String(Math.max(.05,1-scrollY/hero.offsetHeight*1.3)));}}}
  addEventListener('scroll',()=>{if(!scrollFrame)scrollFrame=requestAnimationFrame(updateScroll);},{passive:true});
  if(!isNight){const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){const label=entry.target.querySelector('.section-heading .eyebrow')?.textContent||'ISSUE 26';document.querySelector('.chapter-label').textContent=label;ducked=entry.target.id==='letter';level();}});},{rootMargin:'-20% 0px -40% 0px',threshold:0});document.querySelectorAll('main>section').forEach(s=>observer.observe(s));}
  document.addEventListener('visibilitychange',()=>{if(document.hidden){const was=playing;pause();safeSet('bahram-resume',was);}else if(safeGet('bahram-resume')==='true'){safeSet('bahram-resume',false);play();}});
  addEventListener('pagehide',()=>{if(audio)safeSet(timeKey(),audio.currentTime);clearInterval(timer);audio?.pause();ctx?.suspend();});
  async function init(){await restoreLocalTrack();if(!safeGet('bahram-entered')&&!isNight){const intro=document.createElement('div');intro.className='experience-intro';intro.setAttribute('role','dialog');intro.setAttribute('aria-modal','true');intro.setAttribute('aria-label','Открыть поздравительный выпуск');intro.innerHTML='<div class="intro-center"><span class="eyebrow">ПЕРСОНАЛЬНЫЙ ВЫПУСК · 05 НОЯБРЯ</span><div class="intro-issue">26<span>BAHRAM</span></div><p>Сегодня всё внимание — тебе.<br>Да, реакции обязательны.</p><button class="intro-start">Включить этот вечер <span>↗</span></button><button class="intro-silent">Открыть без звука</button></div>';document.body.append(intro);const background=[...document.body.children].filter(x=>x!==intro&&!['SCRIPT','STYLE','LINK'].includes(x.tagName));background.forEach(x=>x.inert=true);const finish=async sound=>{safeSet('bahram-entered',true);intro.classList.add('leaving');background.forEach(x=>x.inert=false);if(sound)await play();document.querySelector('.hero-copy a')?.focus({preventScroll:true});setTimeout(()=>intro.remove(),650);};intro.querySelector('.intro-start').addEventListener('click',()=>finish(true));intro.querySelector('.intro-silent').addEventListener('click',()=>finish(false));intro.querySelector('.intro-start').focus({preventScroll:true});}else if(safeGet('bahram-playing')==='true'||safeGet('bahram-resume')==='true')play();}
  window.BahramSound={play,pause,duck:state=>{ducked=state;level();},get playing(){return playing;}};
  init();updateScroll();
})();
